 */
@Repository
public class IdempotencyRepository {

    /** 已存储的成功结果，重放时原样返回状态码与响应体。 */
    public record IdempotentRow(
            String requestId,
            String actorId,
            String role,
            String operation,
            String fingerprint,
            int responseStatus,
            String responseBody,
